import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Optical Phenomena","description":"","frontmatter":{"title":"Optical Phenomena"},"headers":[],"relativePath":"classification/optical-phenomena/intro.md","filePath":"classification/optical-phenomena/intro.md","lastUpdated":1790876393000}'),o={name:"classification/optical-phenomena/intro.md"};function l(s,e,i,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="optical-phenomena" tabindex="-1">Optical Phenomena <a class="header-anchor" href="#optical-phenomena" aria-label="Permalink to &quot;Optical Phenomena&quot;">​</a></h1><p>Beyond base color, gems exhibit distinct optical phenomena through internal structure. The seven below are the most representative and observable during identification:</p><h2 id="start-with-observation" tabindex="-1">Start with Observation <a class="header-anchor" href="#start-with-observation" aria-label="Permalink to &quot;Start with Observation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phenomenon</th><th>Suggested observation</th><th>Structural clue to look for</th></tr></thead><tbody><tr><td>Asterism (Star Effect)</td><td>Use a point light and slowly rotate the cabochon</td><td>Oriented needles or tubes</td></tr><tr><td>Chatoyancy (Cat&#39;s-Eye Effect)</td><td>Move the light or cabochon and track the band</td><td>Parallel fibers, tubes, or channels</td></tr><tr><td>Color Change</td><td>Compare daylight with a warm incandescent source</td><td>Source spectrum and selective absorption</td></tr><tr><td>Play of Color</td><td>Tilt slowly and watch flashes move across the surface</td><td>Ordered silica-sphere domains</td></tr><tr><td>Adularescence (Moonstone Sheen)</td><td>Rotate the cabochon and watch the floating sheen</td><td>Alternating feldspar lamellae</td></tr><tr><td>Labradorescence (Spectrolite)</td><td>Change the angle and observe metallic flashes</td><td>Compositional feldspar lamellae</td></tr><tr><td>Aventurescence (Sunstone Glitter)</td><td>Tilt the gem so platelets reflect in sequence</td><td>Oriented metallic platelets</td></tr></tbody></table><h2 id="seven-major-phenomena" tabindex="-1">Seven Major Phenomena <a class="header-anchor" href="#seven-major-phenomena" aria-label="Permalink to &quot;Seven Major Phenomena&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phenomenon</th><th>One-line Summary</th></tr></thead><tbody><tr><td><a href="./asterism.html">Asterism (Star Effect)</a></td><td>Parallel needle inclusions reflect light into star rays</td></tr><tr><td><a href="./chatoyancy.html">Chatoyancy (Cat&#39;s-Eye Effect)</a></td><td>Parallel fibers or tubes form a single bright band</td></tr><tr><td><a href="./color-change.html">Color Change</a></td><td>Gem shows distinctly different colors under different light sources</td></tr><tr><td><a href="./play-of-color.html">Play of Color</a></td><td>Angle-dependent spectral flashes shift across the surface</td></tr><tr><td><a href="./adularescence.html">Adularescence (Moonstone Sheen)</a></td><td>Layered internal structure produces soft, floating blue sheen</td></tr><tr><td><a href="./labradorescence.html">Labradorescence (Spectrolite)</a></td><td>Layered internal structure produces vivid metallic iridescence</td></tr><tr><td><a href="./aventurescence.html">Aventurescence (Sunstone Glitter)</a></td><td>Metallic platelets cause sparkly reflections inside the gem</td></tr></tbody></table><p>An observed phenomenon describes an optical appearance, not a final identification by itself. Lighting, cut, viewing angle, and inclusions all affect the result.</p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA: Guide to Phenomenal Gems</a><span>Observation methods and gemological context for optical phenomena</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA: Optical Effects of Phenomenal Cabochons</a><span>Cabochon cuts, lighting, viewing angle, and optical appearance</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./../intro.html">classification overview</a> for the mineralogical framework.</em></p>',9)])])}const f=t(o,[["render",l]]);export{p as __pageData,f as default};
